const msg = $input.first().json.message || {};
const text = (msg.text || msg.caption || '').trim();
const chatId = msg.chat?.id;

if (!text.startsWith('/email')) {
  return [{ json: { skip: true, chatId, reason: 'Nutze /email — siehe README' } }];
}

const body = text.replace(/^\/email\s*/i, '');
const parts = body.split('---');
const header = parts[0] || '';
const letter = (parts[1] || '').trim();

const to = header.match(/^an:\s*(.+)$/im)?.[1]?.trim();
const subject = header.match(/^betreff:\s*(.+)$/im)?.[1]?.trim() || 'Bewerbung';

if (!to) {
  return [{ json: { skip: true, chatId, reason: 'Zeile fehlt: an: email@firma.de' } }];
}

return [{
  json: {
    skip: false,
    chatId,
    to,
    subject,
    body: letter || 'Sehr geehrte Damen und Herren,\n\nanbei meine Bewerbungsunterlagen.\n\nMit freundlichen Grüßen',
    documentFileId: msg.document?.file_id || null,
    documentFileName: msg.document?.file_name || 'anhang.pdf'
  }
}];

